   107→// New creates a proxy server forwarding requests from a consensus client to an execution client.
   108→func New(opts ...Option) (*Builder, error) {
   109→	p := &Builder{
   110→		cfg: &config{
   111→			builderPort: defaultBuilderPort,
   112→			builderHost: defaultBuilderHost,
   113→			logger:      logrus.New(),
   114→		},
   115→	}
   116→	for _, o := range opts {
   117→		if err := o(p); err != nil {
   118→			return nil, err
   119→		}
   120→	}
   121→	if p.cfg.destinationUrl == nil {
   122→		return nil, errors.New("must provide a destination address for request proxying")
   123→	}
   124→	endpoint := network.HttpEndpoint(p.cfg.destinationUrl.String())
   125→	endpoint.Auth.Method = authorization.Bearer
   126→	endpoint.Auth.Value = p.cfg.secret
   127→	execClient, err := network.NewExecutionRPCClient(context.Background(), endpoint, nil)
   128→	if err != nil {
   129→		return nil, err
   130→	}
   131→	router := http.NewServeMux()
   132→	router.Handle("/", p)
   133→	router.HandleFunc(statusPath, func(writer http.ResponseWriter, request *http.Request) {
   134→		writer.WriteHeader(http.StatusOK)
   135→	})
   136→	router.HandleFunc(registerPath, p.registerValidators)
   137→	router.HandleFunc(headerPath, p.handleHeaderRequest)
   138→	router.HandleFunc(blindedPath, p.handleBlindedBlock)
   139→	addr := net.JoinHostPort(p.cfg.builderHost, strconv.Itoa(p.cfg.builderPort))
   140→	srv := &http.Server{
   141→		Handler:           router,
   142→		Addr:              addr,
   143→		ReadHeaderTimeout: time.Second,
   144→	}
   145→	p.address = addr
   146→	p.srv = srv
   147→	p.execClient = execClient
   148→	p.valLock.Lock()
   149→	p.validatorMap = map[string]*eth.ValidatorRegistrationV1{}
   150→	p.valLock.Unlock()
   151→	p.mux = router
   152→	return p, nil
   153→}
   154→
   155→// Address for the proxy server.
   156→func (p *Builder) Address() string {
   157→	return p.address
   158→}
   159→
   160→// Start a proxy server.
   161→func (p *Builder) Start(ctx context.Context) error {
   162→	p.srv.BaseContext = func(listener net.Listener) context.Context {
   163→		return ctx
   164→	}
   165→	p.cfg.logger.WithFields(logrus.Fields{
   166→		"executionAddress": p.cfg.destinationUrl.String(),
   167→	}).Infof("Builder now listening on address %s", p.address)
   168→	go func() {
   169→		if err := p.srv.ListenAndServe(); err != nil {
   170→			p.cfg.logger.Error(err)
   171→		}
   172→	}()
   173→	for {
   174→		<-ctx.Done()
   175→		return p.srv.Shutdown(context.Background())
   176→	}
   177→}
