   179→// ServeHTTP requests from a consensus client to an execution client, modifying in-flight requests
   180→// and/or responses as desired. It also processes any backed-up requests.
   181→func (p *Builder) ServeHTTP(w http.ResponseWriter, r *http.Request) {
   182→	p.cfg.logger.Infof("Received %s request from beacon with url: %s", r.Method, r.URL.Path)
   183→	if p.isBuilderCall(r) {
   184→		p.mux.ServeHTTP(w, r)
   185→		return
   186→	}
   187→	requestBytes, err := parseRequestBytes(r)
   188→	if err != nil {
   189→		p.cfg.logger.WithError(err).Error("Could not parse request")
   190→		return
   191→	}
   192→	execRes, err := p.sendHttpRequest(r, requestBytes)
   193→	if err != nil {
   194→		p.cfg.logger.WithError(err).Error("Could not forward request")
   195→		return
   196→	}
   197→	p.cfg.logger.Infof("Received response for %s request with method %s from %s", r.Method, r.Method, p.cfg.destinationUrl.String())
   198→
   199→	defer func() {
   200→		if err = execRes.Body.Close(); err != nil {
   201→			p.cfg.logger.WithError(err).Error("Could not do close proxy responseGen body")
   202→		}
   203→	}()
   204→
   205→	buf := bytes.NewBuffer([]byte{})
   206→	if _, err = io.Copy(buf, execRes.Body); err != nil {
   207→		p.cfg.logger.WithError(err).Error("Could not copy proxy request body")
   208→		return
   209→	}
   210→	byteResp := bytesutil.SafeCopyBytes(buf.Bytes())
   211→	p.handleEngineCalls(requestBytes, byteResp)
   212→	// Pipe the proxy responseGen to the original caller.
   213→	if _, err = io.Copy(w, buf); err != nil {
   214→		p.cfg.logger.WithError(err).Error("Could not copy proxy request body")
   215→		return
   216→	}
   217→}
   218→
   219→func (p *Builder) handleEngineCalls(req, resp []byte) {
   220→	if !isEngineAPICall(req) {
   221→		return
   222→	}
   223→	rpcObj, err := unmarshalRPCObject(req)
   224→	if err != nil {
   225→		p.cfg.logger.WithError(err).Error("Could not unmarshal rpc object")
   226→		return
   227→	}
   228→	p.cfg.logger.Infof("Received engine call %s", rpcObj.Method)
   229→	switch rpcObj.Method {
   230→	case ForkchoiceUpdatedMethod, ForkchoiceUpdatedMethodV2, ForkchoiceUpdatedMethodV3:
   231→		result := &ForkchoiceUpdatedResponse{}
   232→		err = json.Unmarshal(resp, result)
   233→		if err != nil {
   234→			p.cfg.logger.Errorf("Could not unmarshal fcu: %v", err)
   235→			return
   236→		}
   237→		if result.Result.PayloadId != nil && *result.Result.PayloadId != [8]byte{} {
   238→			p.currId = result.Result.PayloadId
   239→		}
   240→		if rpcObj.Method == ForkchoiceUpdatedMethodV3 {
   241→			attr := &v1.PayloadAttributesV3{}
   242→			obj, err := json.Marshal(rpcObj.Params[1])
   243→			if err != nil {
   244→				p.cfg.logger.Errorf("Could not marshal attr: %v", err)
   245→				return
   246→			}
   247→			if err := json.Unmarshal(obj, attr); err != nil {
   248→				p.cfg.logger.Errorf("Could not unmarshal attr: %v", err)
   249→				return
   250→			}
   251→			p.prevBeaconRoot = attr.ParentBeaconBlockRoot
   252→		}
   253→		payloadID := [8]byte{}
   254→		status := ""
   255→		var lastValHash []byte
   256→		if result.Result.PayloadId != nil {
   257→			payloadID = *result.Result.PayloadId
   258→		}
   259→		if result.Result.Status != nil {
   260→			status = result.Result.Status.Status.String()
   261→			lastValHash = result.Result.Status.LatestValidHash
   262→		}
   263→		p.cfg.logger.Infof("Received payload id of %#x and status of %s along with a valid hash of %#x", payloadID, status, lastValHash)
   264→	}
   265→}
   266→
   267→func (*Builder) isBuilderCall(req *http.Request) bool {
   268→	return strings.Contains(req.URL.Path, "/eth/v1/builder/")
   269→}
   270→
   271→func (p *Builder) registerValidators(w http.ResponseWriter, req *http.Request) {
   272→	var registrations []structs.SignedValidatorRegistration
   273→	if err := json.NewDecoder(req.Body).Decode(&registrations); err != nil {
   274→		http.Error(w, "invalid request", http.StatusBadRequest)
   275→		return
   276→	}
   277→	for _, r := range registrations {
   278→		msg, err := r.Message.ToConsensus()
   279→		if err != nil {
   280→			http.Error(w, err.Error(), http.StatusInternalServerError)
   281→			return
   282→		}
   283→		p.valLock.Lock()
   284→		p.validatorMap[r.Message.Pubkey] = msg
   285→		p.valLock.Unlock()
   286→	}
   287→	// TODO: Verify Signatures from validators
   288→	w.WriteHeader(http.StatusOK)
   289→}
