   291→func (p *Builder) handleHeaderRequest(w http.ResponseWriter, req *http.Request) {
   292→	pHash := req.PathValue("parent_hash")
   293→	if pHash == "" {
   294→		http.Error(w, "no valid parent hash", http.StatusBadRequest)
   295→		return
   296→	}
   297→	_, err := bytesutil.DecodeHexWithLength(pHash, common.HashLength)
   298→	if err != nil {
   299→		http.Error(w, "invalid parent hash", http.StatusBadRequest)
   300→		return
   301→	}
   302→	reqSlot := req.PathValue("slot")
   303→	if reqSlot == "" {
   304→		http.Error(w, "no valid slot provided", http.StatusBadRequest)
   305→		return
   306→	}
   307→	slot, err := strconv.Atoi(reqSlot)
   308→	if err != nil {
   309→		http.Error(w, "invalid slot provided", http.StatusBadRequest)
   310→		return
   311→	}
   312→	reqPubkey := req.PathValue("pubkey")
   313→	if reqPubkey == "" {
   314→		http.Error(w, "no valid pubkey provided", http.StatusBadRequest)
   315→		return
   316→	}
   317→	_, err = bytesutil.DecodeHexWithLength(reqPubkey, fieldparams.BLSPubkeyLength)
   318→	if err != nil {
   319→		http.Error(w, "invalid pubkey", http.StatusBadRequest)
   320→		return
   321→	}
   322→	ax := types.Slot(slot)
   323→	currEpoch := types.Epoch(ax / params.BeaconConfig().SlotsPerEpoch)
   324→	if currEpoch >= params.BeaconConfig().ElectraForkEpoch {
   325→		p.handleHeaderRequestElectra(w)
   326→		return
   327→	}
   328→
   329→	if currEpoch >= params.BeaconConfig().DenebForkEpoch {
   330→		p.handleHeaderRequestDeneb(w)
   331→		return
   332→	}
   333→
   334→	if currEpoch >= params.BeaconConfig().CapellaForkEpoch {
   335→		p.handleHeaderRequestCapella(w)
   336→		return
   337→	}
   338→
   339→	b, err := p.retrievePendingBlock()
   340→	if err != nil {
   341→		p.cfg.logger.WithError(err).Error("Could not retrieve pending block")
   342→		http.Error(w, err.Error(), http.StatusInternalServerError)
   343→		return
   344→	}
   345→	secKey, err := bls.RandKey()
   346→	if err != nil {
   347→		p.cfg.logger.WithError(err).Error("Could not retrieve secret key")
   348→		http.Error(w, err.Error(), http.StatusInternalServerError)
   349→		return
   350→	}
   351→	wObj, err := blocks.WrappedExecutionPayload(b)
   352→	if err != nil {
   353→		p.cfg.logger.WithError(err).Error("Could not wrap execution payload")
   354→		http.Error(w, err.Error(), http.StatusInternalServerError)
   355→		return
   356→	}
   357→	hdr, err := blocks.PayloadToHeader(wObj)
   358→	if err != nil {
   359→		p.cfg.logger.WithError(err).Error("Could not make payload into header")
   360→		http.Error(w, err.Error(), http.StatusInternalServerError)
   361→		return
   362→	}
   363→	gEth := big.NewInt(int64(params.BeaconConfig().GweiPerEth))
   364→	weiEth := gEth.Mul(gEth, gEth)
   365→	val := builderAPI.Uint256{Int: weiEth}
   366→
   367→	wrappedHdr, err := structs.ExecutionPayloadHeaderFromConsensus(hdr)
   368→	if err != nil {
   369→		p.cfg.logger.WithError(err).Error("Could not convert wrapped header")
   370→		http.Error(w, err.Error(), http.StatusInternalServerError)
   371→		return
   372→	}
   373→	bid := &builderAPI.BuilderBid{
   374→		Header: wrappedHdr,
   375→		Value:  val,
   376→		Pubkey: secKey.PublicKey().Marshal(),
   377→	}
   378→	sszBid := &eth.BuilderBid{
   379→		Header: hdr,
   380→		Value:  val.SSZBytes(),
   381→		Pubkey: secKey.PublicKey().Marshal(),
   382→	}
   383→	d, err := signing.ComputeDomain(params.BeaconConfig().DomainApplicationBuilder,
   384→		nil, /* fork version */
   385→		nil /* genesis val root */)
   386→	if err != nil {
   387→		p.cfg.logger.WithError(err).Error("Could not compute the domain")
   388→		http.Error(w, err.Error(), http.StatusInternalServerError)
   389→		return
   390→	}
   391→	rt, err := signing.ComputeSigningRoot(sszBid, d)
   392→	if err != nil {
   393→		p.cfg.logger.WithError(err).Error("Could not compute the signing root")
   394→		http.Error(w, err.Error(), http.StatusInternalServerError)
   395→		return
   396→	}
   397→	sig := secKey.Sign(rt[:])
   398→	hdrResp := &builderAPI.ExecHeaderResponse{
   399→		Version: "bellatrix",
   400→		Data: struct {
   401→			Signature hexutil.Bytes          `json:"signature"`
   402→			Message   *builderAPI.BuilderBid `json:"message"`
   403→		}{
   404→			Signature: sig.Marshal(),
   405→			Message:   bid,
   406→		},
   407→	}
   408→	w.WriteHeader(http.StatusOK)
   409→	err = json.NewEncoder(w).Encode(hdrResp)
   410→	if err != nil {
   411→		p.cfg.logger.WithError(err).Error("Could not encode response")
   412→		http.Error(w, err.Error(), http.StatusInternalServerError)
   413→		return
   414→	}
   415→	p.currVersion = version.Bellatrix
   416→	p.currPayload = wObj
   417→}
   418→
   419→func (p *Builder) handleHeaderRequestCapella(w http.ResponseWriter) {
   420→	b, err := p.retrievePendingBlockCapella()
   421→	if err != nil {
   422→		p.cfg.logger.WithError(err).Error("Could not retrieve pending block")
   423→		http.Error(w, err.Error(), http.StatusInternalServerError)
   424→		return
   425→	}
   426→
   427→	secKey, err := bls.RandKey()
   428→	if err != nil {
   429→		p.cfg.logger.WithError(err).Error("Could not retrieve secret key")
   430→		http.Error(w, err.Error(), http.StatusInternalServerError)
   431→		return
   432→	}
   433→	v := big.NewInt(0).SetBytes(bytesutil.ReverseByteOrder(b.Value))
   434→	// we set the payload value as twice its actual one so that it always chooses builder payloads vs local payloads
   435→	v = v.Mul(v, big.NewInt(2))
   436→	wObj, err := blocks.WrappedExecutionPayloadCapella(b.Payload)
   437→	if err != nil {
   438→		p.cfg.logger.WithError(err).Error("Could not wrap execution payload")
   439→		http.Error(w, err.Error(), http.StatusInternalServerError)
   440→		return
   441→	}
   442→	hdr, err := blocks.PayloadToHeaderCapella(wObj)
   443→	if err != nil {
   444→		p.cfg.logger.WithError(err).Error("Could not make payload into header")
   445→		http.Error(w, err.Error(), http.StatusInternalServerError)
   446→		return
   447→	}
   448→	val := builderAPI.Uint256{Int: v}
   449→	wrappedHdr, err := structs.ExecutionPayloadHeaderCapellaFromConsensus(hdr)
   450→	if err != nil {
   451→		p.cfg.logger.WithError(err).Error("Could not make execution payload")
   452→		http.Error(w, err.Error(), http.StatusInternalServerError)
   453→		return
   454→	}
   455→	bid := &builderAPI.BuilderBidCapella{
   456→		Header: wrappedHdr,
   457→		Value:  val,
   458→		Pubkey: secKey.PublicKey().Marshal(),
   459→	}
   460→	sszBid := &eth.BuilderBidCapella{
   461→		Header: hdr,
   462→		Value:  val.SSZBytes(),
   463→		Pubkey: secKey.PublicKey().Marshal(),
   464→	}
   465→	d, err := signing.ComputeDomain(params.BeaconConfig().DomainApplicationBuilder,
   466→		nil, /* fork version */
   467→		nil /* genesis val root */)
   468→	if err != nil {
   469→		p.cfg.logger.WithError(err).Error("Could not compute the domain")
   470→		http.Error(w, err.Error(), http.StatusInternalServerError)
   471→		return
   472→	}
   473→	rt, err := signing.ComputeSigningRoot(sszBid, d)
   474→	if err != nil {
   475→		p.cfg.logger.WithError(err).Error("Could not compute the signing root")
   476→		http.Error(w, err.Error(), http.StatusInternalServerError)
   477→		return
   478→	}
   479→	sig := secKey.Sign(rt[:])
   480→	hdrResp := &builderAPI.ExecHeaderResponseCapella{
   481→		Version: "capella",
   482→		Data: struct {
   483→			Signature hexutil.Bytes                 `json:"signature"`
   484→			Message   *builderAPI.BuilderBidCapella `json:"message"`
   485→		}{
   486→			Signature: sig.Marshal(),
   487→			Message:   bid,
   488→		},
   489→	}
   490→	w.WriteHeader(http.StatusOK)
   491→	err = json.NewEncoder(w).Encode(hdrResp)
   492→	if err != nil {
   493→		p.cfg.logger.WithError(err).Error("Could not encode response")
   494→		http.Error(w, err.Error(), http.StatusInternalServerError)
   495→		return
   496→	}
   497→	p.currVersion = version.Capella
   498→	p.currPayload = wObj
   499→}
