   501→func (p *Builder) handleHeaderRequestDeneb(w http.ResponseWriter) {
   502→	b, err := p.retrievePendingBlockDeneb()
   503→	if err != nil {
   504→		p.cfg.logger.WithError(err).Error("Could not retrieve pending block")
   505→		http.Error(w, err.Error(), http.StatusInternalServerError)
   506→		return
   507→	}
   508→
   509→	secKey, err := bls.RandKey()
   510→	if err != nil {
   511→		p.cfg.logger.WithError(err).Error("Could not retrieve secret key")
   512→		http.Error(w, err.Error(), http.StatusInternalServerError)
   513→		return
   514→	}
   515→	v := big.NewInt(0).SetBytes(bytesutil.ReverseByteOrder(b.Value))
   516→	// we set the payload value as twice its actual one so that it always chooses builder payloads vs local payloads
   517→	v = v.Mul(v, big.NewInt(2))
   518→	wObj, err := blocks.WrappedExecutionPayloadDeneb(b.Payload)
   519→	if err != nil {
   520→		p.cfg.logger.WithError(err).Error("Could not wrap execution payload")
   521→		http.Error(w, err.Error(), http.StatusInternalServerError)
   522→		return
   523→	}
   524→
   525→	hdr, err := blocks.PayloadToHeaderDeneb(wObj)
   526→	if err != nil {
   527→		p.cfg.logger.WithError(err).Error("Could not make payload into header")
   528→		http.Error(w, err.Error(), http.StatusInternalServerError)
