   531→	val := builderAPI.Uint256{Int: v}
   532→	var commitments []hexutil.Bytes
   533→	for _, c := range b.BlobsBundle.KzgCommitments {
   534→		copiedC := c
   535→		commitments = append(commitments, copiedC)
