   537→	wrappedHdr, err := structs.ExecutionPayloadHeaderDenebFromConsensus(hdr)
   538→	if err != nil {
   539→		p.cfg.logger.WithError(err).Error("Could not make execution payload")
   540→		http.Error(w, err.Error(), http.StatusInternalServerError)
   541→		return
   542→	}
   543→	bid := &builderAPI.BuilderBidDeneb{
