   592→func (p *Builder) handleHeaderRequestElectra(w http.ResponseWriter) {
   593→	b, err := p.retrievePendingBlockElectra()
   594→	if err != nil {
   595→		p.cfg.logger.WithError(err).Error("Could not retrieve pending block")
