   606→	v := big.NewInt(0).SetBytes(bytesutil.ReverseByteOrder(b.Value))
   607→	// we set the payload value as twice its actual one so that it always chooses builder payloads vs local payloads
   608→	v = v.Mul(v, big.NewInt(2))
   609→	wObj, err := blocks.WrappedExecutionPayloadDeneb(b.Payload)
