   642→	bid := &builderAPI.BuilderBidElectra{
   643→		Header:             wrappedHdr,
   644→		BlobKzgCommitments: commitments,
   645→		Value:              val,
   646→		Pubkey:             secKey.PublicKey().Marshal(),
   647→		ExecutionRequests:  rv1,
