   657→	d, err := signing.ComputeDomain(params.BeaconConfig().DomainApplicationBuilder,
   658→		nil, /* fork version */
   659→		nil /* genesis val root */)
   660→	if err != nil {
   661→		p.cfg.logger.WithError(err).Error("Could not compute the domain")
   662→		http.Error(w, err.Error(), http.StatusInternalServerError)
   663→		return
