   665→	rt, err := signing.ComputeSigningRoot(sszBid, d)
   666→	if err != nil {
   667→		p.cfg.logger.WithError(err).Error("Could not compute the signing root")
   668→		http.Error(w, err.Error(), http.StatusInternalServerError)
   669→		return
   670→	}
   671→	sig := secKey.Sign(rt[:])
   672→	hdrResp := &builderAPI.ExecHeaderResponseElectra{
   673→		Version: "electra",
   674→		Data: struct {
