   727→// ExecutionPayloadResponseFromData converts an ExecutionData interface value to a payload response.
   728→// This involves serializing the execution payload value so that the abstract payload envelope can be used.
   729→func ExecutionPayloadResponseFromData(v int, ed interfaces.ExecutionData, bundle *v1.BlobsBundle) (*builderAPI.ExecutionPayloadResponse, error) {
   730→	pb := ed.Proto()
   731→	var data interface{}
   732→	var err error
   733→	ver := version.String(v)
   734→	switch pbStruct := pb.(type) {
   735→	case *v1.ExecutionPayloadDeneb:
   736→		payloadStruct, err := structs.ExecutionPayloadDenebFromConsensus(pbStruct)
   737→		if err != nil {
   738→			return nil, errors.Wrap(err, "failed to convert a Deneb ExecutionPayload to an API response")
   739→		}
   740→		data = &builderAPI.ExecutionPayloadDenebAndBlobsBundle{
   741→			ExecutionPayload: payloadStruct,
   742→			BlobsBundle:      builderAPI.FromBundleProto(bundle),
   743→		}
   744→	case *v1.ExecutionPayloadCapella:
   745→		data, err = structs.ExecutionPayloadCapellaFromConsensus(pbStruct)
   746→		if err != nil {
   747→			return nil, errors.Wrap(err, "failed to convert a Capella ExecutionPayload to an API response")
   748→		}
   749→	case *v1.ExecutionPayload:
   750→		data, err = structs.ExecutionPayloadFromConsensus(pbStruct)
   751→		if err != nil {
   752→			return nil, errors.Wrap(err, "failed to convert a Bellatrix ExecutionPayload to an API response")
   753→		}
   754→	default:
   755→		return nil, errInvalidTypeConversion
   756→	}
   757→	encoded, err := json.Marshal(data)
   758→	if err != nil {
   759→		return nil, errors.Wrapf(err, "failed to marshal execution payload version=%s", ver)
   760→	}
   761→	return &builderAPI.ExecutionPayloadResponse{
   762→		Version: ver,
   763→		Data:    encoded,
   764→	}, nil
   765→}
