   876→func (p *Builder) sendHttpRequest(req *http.Request, requestBytes []byte) (*http.Response, error) {
   877→	proxyReq, err := http.NewRequest(req.Method, p.cfg.destinationUrl.String(), req.Body)
   878→	if err != nil {
   879→		p.cfg.logger.WithError(err).Error("Could not create new request")
   880→		return nil, err
   881→	}
   882→
   883→	// Set the modified request as the proxy request body.
   884→	proxyReq.Body = io.NopCloser(bytes.NewBuffer(requestBytes))
   885→
   886→	// Required proxy headers for forwarding JSON-RPC requests to the execution client.
   887→	proxyReq.Header.Set("Host", req.Host)
   888→	proxyReq.Header.Set("X-Forwarded-For", req.RemoteAddr)
   889→	proxyReq.Header.Set("Content-Type", "application/json")
   890→
   891→	client := &http.Client{}
   892→	if p.cfg.secret != "" {
   893→		client = network.NewHttpClientWithSecret(p.cfg.secret, "")
   894→	}
   895→	proxyRes, err := client.Do(proxyReq)
   896→	if err != nil {
   897→		p.cfg.logger.WithError(err).Error("Could not forward request to destination server")
   898→		return nil, err
   899→	}
   900→	return proxyRes, nil
   901→}
