   903→// Peek into the bytes of an HTTP request's body.
   904→func parseRequestBytes(req *http.Request) ([]byte, error) {
   905→	requestBytes, err := io.ReadAll(req.Body)
   906→	if err != nil {
   907→		return nil, err
   908→	}
   909→	if err = req.Body.Close(); err != nil {
   910→		return nil, err
   911→	}
   912→	req.Body = io.NopCloser(bytes.NewBuffer(requestBytes))
   913→	return requestBytes, nil
   914→}
