   916→// Checks whether the JSON-RPC request is for the Ethereum engine API.
   917→func isEngineAPICall(reqBytes []byte) bool {
   918→	jsonRequest, err := unmarshalRPCObject(reqBytes)
   919→	if err != nil {
   920→		switch {
   921→		case strings.Contains(err.Error(), "cannot unmarshal array"):
   922→			return false
   923→		default:
   924→			return false
   925→		}
   926→	}
   927→	return strings.Contains(jsonRequest.Method, "engine_")
   928→}
