   938→func modifyExecutionPayload(execPayload engine.ExecutableData, fees *big.Int, prevBeaconRoot []byte, requests [][]byte) (*engine.ExecutionPayloadEnvelope, error) {
   939→	modifiedBlock, err := executableDataToBlock(execPayload, prevBeaconRoot, requests)
   940→	if err != nil {
   941→		return &engine.ExecutionPayloadEnvelope{}, err
   942→	}
   943→	return engine.BlockToExecutableData(modifiedBlock, fees, nil /*blobs*/, requests /*requests*/), nil
