   946→// This modifies the provided payload to imprint the builder's extra data
   947→func executableDataToBlock(params engine.ExecutableData, prevBeaconRoot []byte, requests [][]byte) (*gethTypes.Block, error) {
   948→	txs, err := decodeTransactions(params.Transactions)
   949→	if err != nil {
   950→		return nil, err
   951→	}
   952→	// Only set withdrawalsRoot if it is non-nil. This allows CLs to use
   953→	// ExecutableData before withdrawals are enabled by marshaling
   954→	// Withdrawals as the json null value.
   955→	var withdrawalsRoot *common.Hash
   956→	if params.Withdrawals != nil {
   957→		h := gethTypes.DeriveSha(gethTypes.Withdrawals(params.Withdrawals), trie.NewStackTrie(nil))
   958→		withdrawalsRoot = &h
   959→	}
   960→
   961→	var requestsHash *common.Hash
   962→	if requests != nil {
   963→		h := gethTypes.CalcRequestsHash(requests)
   964→		requestsHash = &h
   965→	}
   966→
   967→	header := &gethTypes.Header{
   968→		ParentHash:      params.ParentHash,
   969→		UncleHash:       gethTypes.EmptyUncleHash,
   970→		Coinbase:        params.FeeRecipient,
   971→		Root:            params.StateRoot,
   972→		TxHash:          gethTypes.DeriveSha(gethTypes.Transactions(txs), trie.NewStackTrie(nil)),
   973→		ReceiptHash:     params.ReceiptsRoot,
   974→		Bloom:           gethTypes.BytesToBloom(params.LogsBloom),
   975→		Difficulty:      common.Big0,
   976→		Number:          new(big.Int).SetUint64(params.Number),
   977→		GasLimit:        params.GasLimit,
   978→		GasUsed:         params.GasUsed,
   979→		Time:            params.Timestamp,
   980→		BaseFee:         params.BaseFeePerGas,
   981→		Extra:           []byte("prysm-builder"), // add in extra data
   982→		MixDigest:       params.Random,
   983→		WithdrawalsHash: withdrawalsRoot,
   984→		BlobGasUsed:     params.BlobGasUsed,
   985→		ExcessBlobGas:   params.ExcessBlobGas,
   986→		RequestsHash:    requestsHash,
   987→	}
   988→
   989→	if prevBeaconRoot != nil {
   990→		pRoot := common.Hash(prevBeaconRoot)
   991→		header.ParentBeaconRoot = &pRoot
   992→	}
   993→
   994→	body := gethTypes.Body{
   995→		Transactions: txs,
   996→		Uncles:       nil,
   997→		Withdrawals:  params.Withdrawals,
   998→	}
   999→	block := gethTypes.NewBlockWithHeader(header).WithBody(body)
  1000→	return block, nil
  1001→}
  1002→
  1003→func decodeTransactions(enc [][]byte) ([]*gethTypes.Transaction, error) {
  1004→	var txs = make([]*gethTypes.Transaction, len(enc))
  1005→	for i, encTx := range enc {
  1006→		var tx gethTypes.Transaction
  1007→		if err := tx.UnmarshalBinary(encTx); err != nil {
  1008→			return nil, fmt.Errorf("invalid transaction %d: %w", i, err)
  1009→		}
  1010→		txs[i] = &tx
  1011→	}
  1012→	return txs, nil
  1013→}
