   136→func verifyDepositDataWithDomain(ctx context.Context, deps []*ethpb.Deposit, domain []byte) error {
   137→	if len(deps) == 0 {
   138→		return nil
   139→	}
   140→	pks := make([]bls.PublicKey, len(deps))
   141→	sigs := make([][]byte, len(deps))
   142→	msgs := make([][32]byte, len(deps))
   143→	for i, dep := range deps {
   144→		if ctx.Err() != nil {
   145→			return ctx.Err()
   146→		}
   147→		if dep == nil || dep.Data == nil {
   148→			return errors.New("nil deposit")
   149→		}
   150→		dpk, err := bls.PublicKeyFromBytes(dep.Data.PublicKey)
   151→		if err != nil {
   152→			return err
   153→		}
   154→		pks[i] = dpk
   155→		sigs[i] = dep.Data.Signature
   156→		depositMessage := &ethpb.DepositMessage{
   157→			PublicKey:             dep.Data.PublicKey,
   158→			WithdrawalCredentials: dep.Data.WithdrawalCredentials,
   159→			Amount:                dep.Data.Amount,
   160→		}
   161→		sr, err := signing.ComputeSigningRoot(depositMessage, domain)
   162→		if err != nil {
   163→			return err
   164→		}
   165→		msgs[i] = sr
   166→	}
   167→	verify, err := bls.VerifyMultipleSignatures(sigs, msgs, pks)
   168→	if err != nil {
   169→		return errors.Errorf("could not verify multiple signatures: %v", err)
   170→	}
   171→	if !verify {
   172→		return errors.New("one or more deposit signatures did not verify")
   173→	}
   174→	return nil
   175→}
