   149→type sszUnmarshaler interface {
   150→	UnmarshalSSZ([]byte) error
   151→}
   152→
   153→type sszMarshaler interface {
   154→	MarshalSSZTo(buf []byte) ([]byte, error)
   155→	SizeSSZ() int
   156→}
   157→
   158→func marshalItems[T sszMarshaler](items []T) ([]byte, error) {
   159→	if len(items) == 0 {
   160→		return []byte{}, nil
   161→	}
   162→	size := items[0].SizeSSZ()
   163→	buf := make([]byte, 0, size*len(items))
   164→	var err error
   165→	for i, item := range items {
   166→		buf, err = item.MarshalSSZTo(buf)
   167→		if err != nil {
   168→			return nil, fmt.Errorf("failed to marshal item at index %d: %w", i, err)
   169→		}
   170→	}
   171→	return buf, nil
   172→}
   173→
   174→// Generic function to unmarshal items
   175→func unmarshalItems[T sszUnmarshaler](data []byte, itemSize int, newItem func() T) ([]T, error) {
   176→	if len(data)%itemSize != 0 {
   177→		return nil, fmt.Errorf("invalid data length: data size (%d) is not a multiple of item size (%d)", len(data), itemSize)
   178→	}
   179→	numItems := len(data) / itemSize
   180→	items := make([]T, numItems)
   181→	for i := range items {
   182→		itemBytes := data[i*itemSize : (i+1)*itemSize]
   183→		item := newItem()
   184→		if err := item.UnmarshalSSZ(itemBytes); err != nil {
   185→			return nil, fmt.Errorf("failed to unmarshal item at index %d: %w", i, err)
   186→		}
   187→		items[i] = item
   188→	}
   189→	return items, nil
   190→}
