   283→// createGenesisTime adds in the genesis delay to the eth1 block time
   284→// on which it was triggered.
   285→func createGenesisTime(timeStamp uint64) uint64 {
   286→	return timeStamp + params.BeaconConfig().GenesisDelay
   287→}
